ground_truth_sql:
SELECT "nct", "author", "year", "publication_type", "ici_name", "trial_phase", "cancer_type"
FROM public."clinical_trials"
WHERE "ici_name" = 'Nivolumab, Ipilimumab' AND "cancer_type" = 'Non-Small Cell Lung' AND "trial_phase" = 'Phase 3' AND "publication_type" = 'Original publication';

gt_sql_final:
SELECT "nct", "author", "year", "originial_publication_or_follow_up", "name_of_ici", "trial_phase", "cancer_type"
FROM public."clinical_trials"
WHERE "name_of_ici" = 'Nivolumab, Ipilimumab' AND "cancer_type" = 'Non-Small Cell Lung' AND "trial_phase" = 'Phase 3' AND "originial_publication_or_follow_up" = 'Original publication';
